import { describe, it } from 'vitest'
import * as power from '../../src/power/preExperiment.js'
import { expectParity } from '../parity/compare.js'
import { decode, loadFixture } from '../parity/fixtures.js'

// Generated by the coordinator's train from upstream, never from the local port.
// These tests arm as soon as their named fixtures exist.
for (const name of ['powerEstFrequentist', 'powerFrequentist', 'findMdeFrequentist', 'powerEstBayesian', 'findMdeBayesian', 'powerMetricWeeks'] as const) {
  const fixtureName = `power.${name}`
  const fixture = loadFixture(fixtureName)
  describe(fixtureName, () => {
    if (!fixture) {
      it.skip('awaits upstream fixture generation on the coordinator train', () => {})
      return
    }
    for (const { name: caseName, input, expected } of fixture.cases) {
      it(caseName, () => {
        const fn = power[name] as (...args: any[]) => unknown
        expectParity(fn(...decode(input.args)), decode(expected))
      })
    }
  })
}
